CREATE OR REPLACE FUNCTION public.fn_get_branch_operational_goals(p_tenant_id uuid, p_branch_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, branch_name character varying, title character varying, category character varying, target_metric character varying, current_value character varying, target_value character varying, status character varying, target_date date, owner_name character varying, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          g.id,         g.tenant_id AS tenant_id,         g.organization_id AS organization_id,         g.branch_id AS branch_id,         b.name AS branch_name,         g.title AS title,         g.category AS category,         g.target_metric AS target_metric,         g.current_value AS current_value,         g.target_value AS target_value,         g.status AS status,         g.target_date AS target_date,         g.owner_name AS owner_name,         g.created_at AS created_at,         g.updated_at AS updated_at     FROM branch_operational_goals g     LEFT JOIN branches b ON g.branch_id = b.id     WHERE g.tenant_id = p_tenant_id       AND (p_branch_id IS NULL OR g.branch_id = p_branch_id)     ORDER BY g.created_at DESC; $function$ ;
